113	class _FakeEntriesRepository implements EntriesRepository {
114	  Either<Failure, Entry> Function()? nextResult;
115	  int createCallCount = 0;
116	  EntrySource? lastSource;
117	  int? lastMediaDurationSeconds;
118	
119	  /// Lets a test hold `create()` unresolved, to observe the modal's
120	  /// mid-save state — same convention `insertion_modal_test.dart`'s own
121	  /// `_FakeEntriesRepository.gate` already uses for the Texto tab (Review
122	  /// finding: the Áudio tab had no equivalent coverage of its own
123	  /// `isSaving` gating the tab bar/close button).
124	  Completer<void>? gate;
125	
126	  @override
127	  Future<Either<Failure, Entry>> create({
128	    required String content,
129	    required EntrySource source,
130	    int? mediaDurationSeconds,
131	  }) async {
132	    createCallCount++;
133	    lastSource = source;
134	    lastMediaDurationSeconds = mediaDurationSeconds;
135	    final activeGate = gate;
136	    if (activeGate != null) {
137	      await activeGate.future;
138	    }
139	    return nextResult!();
140	  }
141	}
