1	import 'dart:async';
2	import 'dart:io';
3	import 'dart:typed_data';
4	
5	import 'package:flutter_bloc/flutter_bloc.dart';
6	
7	import '../../../../core/failure/failure.dart';
8	import '../../../entries/domain/entities/entry.dart';
9	import '../../../entries/domain/repositories/entries_repository.dart';
10	import '../../domain/repositories/media_repository.dart';
11	import '../../domain/services/photo_picker.dart';
12	
13	/// `PhotoEntryCubit`'s own sealed state hierarchy — separate from
14	/// `TextEntryState`/`AudioCaptureState` (Boundaries: "own sealed
15	/// `PhotoCaptureState`"). No common base-class field, same rationale as
16	/// `AudioCaptureState`: [PhotoIdle] has nothing in common with
17	/// [PhotoRecognized], for instance.
18	sealed class PhotoCaptureState {
19	  const PhotoCaptureState();
20	}
21	
22	/// The state immediately after the modal opens on the Foto tab, after
23	/// leaving mid-pick/mid-OCR (Never: this story's trivial cross-tab
24	/// case), and the state a fresh `PhotoEntryCubit` always starts in.
25	/// `InsertionModal`'s own `_FotoTab` renders the Câmera/Galeria capture
26	/// buttons for this state.
27	class PhotoIdle extends PhotoCaptureState {
28	  const PhotoIdle();
29	}
30	
31	/// A photo was picked, `MediaRepository.recognizeText()` in flight —
32	/// `_FotoTab` shows a thumbnail + "Reconhecendo texto..." for the whole
33	/// duration of this state (Acceptance Criteria). No separate "recording"-
34	/// style intermediate phase (Design Notes): picking is one blocking OS
35	/// call, so [PhotoIdle] goes straight here once the picker returns a file.
36	class PhotoProcessing extends PhotoCaptureState {
37	  const PhotoProcessing({required this.path, required this.mimeType});
38	
39	  final String path;
40	  final String mimeType;
41	}
42	
43	/// OCR succeeded with usable text — [text] is editable before Salvar
44	/// (Acceptance Criteria), mirrored by [PhotoEntryCubit.updateText].
45	/// [saving] folds `TextEntrySaving`'s role into this same state, same
46	/// convention as `AudioTranscribed.saving`.
47	class PhotoRecognized extends PhotoCaptureState {
48	  const PhotoRecognized({
49	    required this.path,
50	    required this.mimeType,
51	    required this.text,
52	    required this.saving,
53	  });
54	
55	  final String path;
56	  final String mimeType;
57	  final String text;
58	  final bool saving;
59	
60	  PhotoRecognized copyWith({String? text, bool? saving}) => PhotoRecognized(
61	    path: path,
62	    mimeType: mimeType,
63	    text: text ?? this.text,
64	    saving: saving ?? this.saving,
65	  );
66	}
67	
68	/// A save attempt succeeded — `InsertionModal`'s listener reacts to this
69	/// exactly like `TextEntrySaved`/`AudioSaved` (announce, then pop).
70	/// Terminal, same rationale as those two states' own docs.
71	class PhotoSaved extends PhotoCaptureState {
72	  const PhotoSaved();
73	}
74	
75	/// The 3-way discriminator driving `_FotoTab`'s three distinct error
76	/// branches (Design Notes: "a discriminator is clearer than overloading
77	/// nullability tricks" — unlike `AudioError`'s binary `canRetry`, Photo
78	/// has two distinct non-retryable backend codes needing different UI).
79	enum PhotoErrorKind {
80	  /// `Failure.ocrNoText` — "Tentar novamente" (re-OCRs the same image)
81	  /// and "Salvar só a foto" (saves a fixed placeholder) are both offered.
82	  ocrNoText,
83	
84	  /// `Failure.payloadTooLarge` — no retry, no save-without-text; the only
85	  /// way forward is picking a different photo.
86	  payloadTooLarge,
87	
88	  /// Any other `Failure` — a generic OCR-call failure ([text] `null`,
89	  /// "Tentar novamente" re-OCRs) or a save failure ([text] non-null,
90	  /// re-running the failed call means tapping Salvar again, same shape
91	  /// as `AudioError`).
92	  generic,
93	}
94	
95	/// The last attempt failed — covers every failure row of the I/O matrix:
96	/// `OCR_NO_TEXT`, `PAYLOAD_TOO_LARGE`, a generic OCR-call failure, or a
97	/// save failure (non-null [text]).
98	class PhotoError extends PhotoCaptureState {
99	  const PhotoError({
100	    required this.path,
101	    required this.mimeType,
102	    required this.message,
103	    required this.kind,
104	    this.text,
105	  });
106	
107	  final String path;
108	  final String mimeType;
109	  final String message;
110	  final PhotoErrorKind kind;
111	
112	  /// Non-null only for a save failure ([PhotoErrorKind.generic]) — lets
113	  /// `_FotoTab` keep rendering the editable text field under the inline
114	  /// error, same as `AudioError.text`/`TextEntryError`'s own rendering.
115	  final String? text;
116	}
117	
118	/// Drives the Foto tab's pick -> processingOcr -> recognized/error
119	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
120	/// tap, same convention as `TextEntryCubit`/`AudioEntryCubit` —
121	/// [PhotoPicker]/[MediaRepository] themselves stay long-lived `get_it`
122	/// singletons (`capture_injection.dart`).
123	class PhotoEntryCubit extends Cubit<PhotoCaptureState> {
124	  PhotoEntryCubit(
125	    this._photoPicker,
126	    this._mediaRepository,
127	    this._entriesRepository,
128	  ) : super(const PhotoIdle());
129	
130	  final PhotoPicker _photoPicker;
131	  final MediaRepository _mediaRepository;
132	  final EntriesRepository _entriesRepository;
133	
134	  static const _noTextPlaceholder =
135	      'Registro fotográfico (sem texto reconhecido)';
136	
137	  /// Bumped by [cancel] (and by every pick/retry attempt) so an in-flight
138	  /// picker/OCR continuation can tell "the user already left the Foto tab"
139	  /// apart from "nothing has changed since I started" — same role
140	  /// `AudioEntryCubit._generation` plays for the picker call and the OCR
141	  /// network call here (Boundaries).
142	  int _generation = 0;
143	
144	  /// Guards against a second overlapping picker call (e.g. a fast
145	  /// double-tap on Câmera before the UI rebuilds past [PhotoIdle]).
146	  bool _picking = false;
147	
148	  Future<void> pickFromCamera() => _pick(_photoPicker.pickFromCamera);
149	
150	  Future<void> pickFromGallery() => _pick(_photoPicker.pickFromGallery);
151	
152	  Future<void> _pick(Future<PickedPhoto?> Function() pick) async {
153	    final current = state;
154	    final canPick =
155	        !_picking &&
156	        (current is PhotoIdle ||
157	            (current is PhotoError &&
158	                current.kind == PhotoErrorKind.payloadTooLarge));
159	    if (!canPick) {
160	      return;
161	    }
162	    // A fresh pick replacing a previous `payloadTooLarge` error's own
163	    // (never-OCR'd, now-abandoned) file — Review finding: without this,
164	    // that file leaked on disk forever once this new pick's own file
165	    // takes over `state`. Deleted unconditionally right away (Review
166	    // finding): this old file is abandoned the moment a new pick starts,
167	    // regardless of whether that new pick succeeds, is canceled, or
168	    // throws — the earlier code only deleted it on success, leaking it
169	    // on every other exit path.
170	    final previousPath = current is PhotoError ? current.path : null;
171	    if (previousPath != null) {
172	      unawaited(_deletePickedFile(previousPath));
173	    }
174	    _picking = true;
175	    final generation = ++_generation;
176	    PickedPhoto? photo;
177	    try {
178	      photo = await pick();
179	    } catch (_) {
180	      // A thrown PlatformException (native-side error) must never escape
181	      // uncaught — treated the same as a plain user cancel, since this
182	      // story offers no dedicated "picker failed" UI (not in the I/O
183	      // matrix).
184	      _picking = false;
185	      if (isClosed || generation != _generation) {
186	        return;
187	      }
188	      emit(const PhotoIdle());
189	      return;
190	    }
191	    _picking = false;
